// EcoNex - Robust Gemini Result Parser

const input = $input.first().json;

// Get Gemini response from Edit Fields
let raw =
  input.ai_result ??
  input.content?.parts?.[0]?.text ??
  "";

// Convert to string
raw = String(raw).trim();

// Remove markdown code fences if Gemini adds them
raw = raw
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let result;

try {
  result = JSON.parse(raw);
} catch (error) {

  return [
    {
      json: {
        status: "manual_review",
        object_name: null,
        category: null,
        materials: null,
        recyclable: null,
        authorized_recycler_required: null,
        confidence: 0,
        error: "Unable to parse Gemini response",
        raw_response: raw
      }
    }
  ];
}

// Return normalized result
return [
  {
    json: {
      status: result.status ?? null,
      message: result.message ?? null,
      object_name: result.object_name ?? null,
      category: result.category ?? null,
      materials: result.materials ?? null,
      recyclable: result.recyclable ?? null,
      authorized_recycler_required:
        result.authorized_recycler_required ?? null,
      confidence: result.confidence ?? null
    }
  }
];

