const data = $input.first().json;

const planning = data.planning_result;
const recyclers = data.recycler_database || [];

const category = planning.category;
const authorizationRequired =
  planning.required_authorization ?? planning.recycler_required;

// Filter suitable recyclers
const eligibleRecyclers = recyclers.filter(recycler => {

  // Category match
  const categoryMatch =
    Array.isArray(recycler.accepted_categories) &&
    recycler.accepted_categories.includes(category);

  // Authorization check
  const authorizationMatch =
    authorizationRequired !== true ||
    recycler.authorized === true;

  return categoryMatch && authorizationMatch;
});

// Prepare collector-friendly options
const recyclerOptions = eligibleRecyclers.map(recycler => {

  // Get price for the detected category
  const price =
    recycler.pricing &&
    typeof recycler.pricing[category] !== "undefined"
      ? recycler.pricing[category]
      : null;

  return {
    recycler_id: recycler.recycler_id,
    recycler_name: recycler.recycler_name,
    authorized: recycler.authorized,
    category_accepted: category,
    price: price,
    pickup_available: recycler.pickup_available,
    location: recycler.location,
    service_radius_km: recycler.service_radius_km,

    // IMPORTANT: Keep recycler GPS coordinates
    latitude: recycler.latitude,
    longitude: recycler.longitude
  };
});

return [
  {
    json: {
      status: planning.status,
      decision: planning.decision,
      category: category,
      confidence: planning.confidence,
      recycler_required: planning.recycler_required,
      required_authorization: authorizationRequired,

      // Keep collector GPS
      collector_latitude: planning.latitude,
      collector_longitude: planning.longitude,

      suitable_recyclers_count: recyclerOptions.length,
      suitable_recyclers: recyclerOptions
    }
  }
];

