// EcoNex - Calculate Actual Distance

function calculateDistance(lat1, lon1, lat2, lon2) {
  const R = 6371; // Earth radius in km

  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) *
    Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;

  const c = 2 * Math.atan2(
    Math.sqrt(a),
    Math.sqrt(1 - a)
  );

  return R * c;
}


// Get Recycler Matching output
const data = $input.first().json;

// Collector GPS
const collectorLat = Number(data.collector_latitude);
const collectorLon = Number(data.collector_longitude);

if (
  !Number.isFinite(collectorLat) ||
  !Number.isFinite(collectorLon)
) {
  throw new Error("Collector GPS coordinates are missing or invalid.");
}


// Recycler list
const recyclers = data.suitable_recyclers || [];

const updatedRecyclers = recyclers.map(recycler => {

  const recyclerLat = Number(recycler.latitude);
  const recyclerLon = Number(recycler.longitude);

  if (
    !Number.isFinite(recyclerLat) ||
    !Number.isFinite(recyclerLon)
  ) {
    return {
      ...recycler,
      distance_km: null
    };
  }

  const distance = calculateDistance(
    collectorLat,
    collectorLon,
    recyclerLat,
    recyclerLon
  );

  return {
    ...recycler,
    distance_km: Number(distance.toFixed(2))
  };
});


return [
  {
    json: {
      ...data,
      suitable_recyclers: updatedRecyclers
    }
  }
];

const data = $input.first().json;

const recyclers = data.suitable_recyclers || [];

const eligibleRecyclers = recyclers.filter(recycler => {

  const distance = Number(recycler.distance_km);
  const radius = Number(recycler.service_radius_km);

  return (
    Number.isFinite(distance) &&
    Number.isFinite(radius) &&
    distance <= radius
  );
});

return [
  {
    json: {
      ...data,
      suitable_recyclers: eligibleRecyclers,
      suitable_recyclers_count: eligibleRecyclers.length
    }
  }
];
